def is_multiply_prime(a):
    """Return True if the given number is the multiplication of 3 prime numbers, False otherwise.

    Args:
        a (int): The input number.

    Returns:
        bool: Whether the number is the product of three prime numbers.

    Examples:
        is_multiply_prime(30) == True
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        max_divisor = int(n**0.5) + 1
        for d in range(3, max_divisor, 2):
            if n % d == 0:
                return False
        return True

    def get_prime_factors(n):
        """Get all prime factors of a number."""
        factors = []
        i = 2
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    prime_factors = get_prime_factors(a)
    return len(prime_factors) >= 3 and all(is_prime(factor) for factor in prime_factors)
